  ('9a000000-0000-4000-8000-000000000001', 'essential', 'Essential', 'Everything a listing needs to go live tomorrow.', 'Professional listing photography and a clean floor plan — the essentials, done beautifully.', array['Professional listing photography', 'Basic 2D floor plan', 'Next-day delivery', 'MLS-ready sizing']::text[], 25000, '[{"max_sqft":2500,"price_cents":25000},{"max_sqft":3500,"price_cents":29500},{"max_sqft":5000,"price_cents":34500},{"max_sqft":null,"price_cents":42500}]'::jsonb, null, '/media/work/fairmont-lounge.jpg', 'Next-day delivery', false, true, 10),
