  ('9a000000-0000-4000-8000-000000000003', 'signature', 'Signature', 'The cinematic launch for listings that deserve a premiere.', 'Everything in Pro plus a cinematic property film and a vertical reel built for social reach.', array['Professional photography', 'Drone photography', 'Cinematic property video', 'Vertical social media reel', 'Floor plan', 'Property website', 'Marketing kit']::text[], 65000, '[{"max_sqft":2500,"price_cents":65000},{"max_sqft":3500,"price_cents":75000},{"max_sqft":5000,"price_cents":87500},{"max_sqft":null,"price_cents":105000}]'::jsonb, 'Best value', '/media/photos/twilight-rambler.jpg', 'Photos next day · film in 48h', false, true, 30)
