insert into public.portfolio_projects (id, slug, title, client_name, industry, year, headline, summary, description, categories, services_performed, metrics, challenge, strategy, execution, results, cover_image_url, hover_video_url, video_url, city, state, testimonial_quote, testimonial_author, testimonial_role, is_featured, is_published, is_sample, sort_order) values
  ('93000000-0000-4000-8000-000000000001', 'elevate-property-group', 'Elevate Property Group', 'Elevate Property Group', 'Real Estate', 2025, 'A brokerage brand, told by its people.', 'A brand film for Elevate Property Group — the team, the culture and the energy behind the brokerage — cut vertical-first for Instagram and Reels, plus photo and video coverage of the team''s night at the ballpark.', 'A brand film for Elevate Property Group — the team, the culture and the energy behind the brokerage — cut vertical-first for Instagram and Reels, plus photo and video coverage of the team''s night at the ballpark.', array['creative', 'social']::text[], array['Brand Film', 'Content Production', 'Social Media']::text[], '[]'::jsonb, null, null, 'A two-minute brand film shot in 4K: on-camera interviews, event coverage and branded detail shots, finished with burned-in captions for sound-off viewing.', null, '/media/photos/suite-sunset.jpg', '/media/video/elevate.mp4', '/media/video/elevate.mp4', null, null, null, null, null, true, true, false, 10),
  ('93000000-0000-4000-8000-000000000002', 'pet-grand-hotel', 'Pet Grand Hotel', 'Pet Grand Hotel', 'Hospitality', 2025, 'Five-star energy. Four-legged guests.', 'A promo film for a luxury pet hotel — the suites, the play areas and the guests themselves — made to feel like a real hotel tour.', 'A promo film for a luxury pet hotel — the suites, the play areas and the guests themselves — made to feel like a real hotel tour.', array['creative', 'social']::text[], array['Promo Film', 'Content Production']::text[], '[]'::jsonb, null, null, 'Shot in 4K across suites, play yards and grooming rooms, with on-screen labels for each room type so the film doubles as a virtual tour.', null, '/media/work/pet-grand-hotel-03.jpg', '/media/video/pet-grand-hotel.mp4', '/media/video/pet-grand-hotel.mp4', null, null, null, null, null, true, true, false, 20),
  ('93000000-0000-4000-8000-000000000003', 'great-falls-estate', 'Great Falls Estate', 'Private listing', 'Luxury Real Estate', 2025, 'Selling the backyard before the front door.', 'A cinematic listing film for a Great Falls, Virginia estate — outdoor kitchen, pool house and grounds — shot horizontal for YouTube and the MLS, with a vertical cut for social.', 'A cinematic listing film for a Great Falls, Virginia estate — outdoor kitchen, pool house and grounds — shot horizontal for YouTube and the MLS, with a vertical cut for social.', array['creative', 'web']::text[], array['Listing Film', 'Social Cut']::text[], '[]'::jsonb, null, null, 'A gimbal-led walkthrough of the grounds and outdoor living spaces, finished in 4K, plus a separate vertical edit for Instagram.', null, '/media/video/great-falls.jpg', '/media/video/great-falls.mp4', '/media/video/great-falls.mp4', 'Great Falls', 'VA', null, null, null, false, true, false, 30),
  ('93000000-0000-4000-8000-000000000004', 'right-fit-summer-kick-off', 'Summer Kick Off', 'Right Fit Realty', 'Real Estate', 2025, 'The company cookout, captured as a brand story.', 'Event coverage for Right Fit Realty''s Summer Kick Off — agents, families and partners on camera — edited into a recap film and short vertical highlights.', 'Event coverage for Right Fit Realty''s Summer Kick Off — agents, families and partners on camera — edited into a recap film and short vertical highlights.', array['social', 'creative']::text[], array['Event Film', 'Social Media', 'Content Production']::text[], '[]'::jsonb, null, null, 'Run-and-gun 4K coverage with quick on-camera interviews, sponsor moments and branded details, cut into a four-minute recap and vertical highlights.', null, '/media/video/right-fit.jpg', '/media/video/right-fit.mp4', '/media/video/right-fit.mp4', null, null, null, null, null, false, true, false, 40),
  ('93000000-0000-4000-8000-000000000005', 'smart-settlements', 'Smart Settlements', 'Smart Settlements', 'Real Estate Services', 2025, 'Putting faces to the closing table.', 'A brand video for a settlement team — the office, the people and the closing table — edited into a tight one-minute piece for social.', 'A brand video for a settlement team — the office, the people and the closing table — edited into a tight one-minute piece for social.', array['creative', 'social']::text[], array['Brand Video', 'Content Production']::text[], '[]'::jsonb, null, null, 'Walk-and-talk intros, meeting-room b-roll and team moments, shot in 4K and edited to just over a minute.', null, '/media/work/smart-settlements-01.jpg', '/media/video/smart-settlements.mp4', '/media/video/smart-settlements.mp4', null, null, null, null, null, false, true, false, 50),
  ('93000000-0000-4000-8000-000000000006', '2933-north-fairmont-street', '2933 N Fairmont Street', 'Listing launch', 'Residential Real Estate', 2025, 'Just listed — and hard to scroll past.', 'Launch media for a five-bed, four-bath Falls Church home listed at $849,900: an agent-led listing film, HDR photography and a vertical reel for Instagram.', 'Launch media for a five-bed, four-bath Falls Church home listed at $849,900: an agent-led listing film, HDR photography and a vertical reel for Instagram.', array['creative', 'social']::text[], array['Listing Film', 'Photography', 'Social Media']::text[], '[]'::jsonb, null, null, 'An agent-on-camera walkthrough shot in 4K, HDR interiors for the MLS and a captioned reel posted with the listing announcement.', null, '/media/work/fairmont-deck.jpg', '/media/video/fairmont.mp4', '/media/video/fairmont.mp4', 'Falls Church', 'VA', null, null, null, false, true, false, 60),
  ('93000000-0000-4000-8000-000000000007', '17455-kagera-drive', '17455 Kagera Drive', 'Lopez Realtors', 'Residential Real Estate', 2025, 'A listing film with a host.', 'Listing launch for Jenny Lopez of Lopez Realtors — an agent-hosted film, HDR photography and social cuts for the Just Listed push.', 'Listing launch for Jenny Lopez of Lopez Realtors — an agent-hosted film, HDR photography and social cuts for the Just Listed push.', array['creative', 'social']::text[], array['Listing Film', 'Photography', 'Social Media']::text[], '[]'::jsonb, null, null, 'An agent-hosted tour filmed in 4K, paired with a full HDR photo set and a vertical reel for Instagram.', null, '/media/work/kagera-living.jpg', '/media/video/kagera.mp4', '/media/video/kagera.mp4', null, null, null, null, null, false, true, false, 70),
  ('93000000-0000-4000-8000-000000000008', 'isaia', 'Isaia', 'Isaia', 'Fashion & Retail', 2025, 'Neapolitan tailoring, framed like a campaign.', 'Store photography and a vertical reel for Isaia''s boutique — the storefront, the red-lacquered displays and the tailoring up close.', 'Store photography and a vertical reel for Isaia''s boutique — the storefront, the red-lacquered displays and the tailoring up close.', array['creative', 'social']::text[], array['Photography', 'Reels', 'Content Production']::text[], '[]'::jsonb, null, null, 'A full boutique shoot — exteriors, wide interiors and product details — plus a 20-second reel cut for Instagram.', null, '/media/work/isaia-store-1.jpg', '/media/video/isaia.mp4', '/media/video/isaia.mp4', null, null, null, null, null, true, true, false, 5),
  ('93000000-0000-4000-8000-000000000009', 'groom-guy', 'Groom Guy', 'Groom Guy', 'Men''s Grooming', 2025, 'Fresh cuts. Sharper entrances.', 'A cinematic brand spot for Groom Guy — a sharply dressed crew owning a luxury lobby — shot in 4K for Instagram and Reels.', 'A cinematic brand spot for Groom Guy — a sharply dressed crew owning a luxury lobby — shot in 4K for Instagram and Reels.', array['creative', 'social']::text[], array['Brand Film', 'Social Media']::text[], '[]'::jsonb, null, null, 'A choreographed walk-and-reveal through a luxury lobby, shot in 4K on a gimbal and graded for an editorial look.', null, '/media/video/groom.jpg', '/media/video/groom.mp4', '/media/video/groom.mp4', null, null, null, null, null, true, true, false, 15),
  ('93000000-0000-4000-8000-000000000010', 'district-cup', 'District Cup', null, 'Events & Sports', 2025, 'Polo, style and summer in the capital.', 'Event content from the District Cup polo match in D.C. — fast plays, sharp fits and the crowd between chukkers — cut into a vertical recap for Instagram.', 'Event content from the District Cup polo match in D.C. — fast plays, sharp fits and the crowd between chukkers — cut into a vertical recap for Instagram.', array['social', 'creative']::text[], array['Event Coverage', 'Reels']::text[], '[]'::jsonb, null, null, 'Run-and-gun coverage on the field and in the tents, edited into a 27-second recap.', null, '/media/work/polo-01.jpg', '/media/video/polo.mp4', '/media/video/polo.mp4', null, null, null, null, null, false, true, false, 45),
  ('93000000-0000-4000-8000-000000000011', 'tunlaw-penthouse', 'Tunlaw Rd NW Penthouse', null, 'Luxury Real Estate', 2025, 'A penthouse with a skyline terrace, framed to match.', 'A cinematic listing film for a Washington, D.C. penthouse — the open living spaces and the rooftop terrace — cut in widescreen and vertical for the MLS and social.', 'A cinematic listing film for a Washington, D.C. penthouse — the open living spaces and the rooftop terrace — cut in widescreen and vertical for the MLS and social.', array['creative', 'social']::text[], array['Listing Film', 'Vertical Reel']::text[], '[]'::jsonb, null, null, 'Gimbal-shot in 4K, graded for a bright, clean look, with a widescreen edit for the listing page and a vertical cut for Instagram.', null, '/media/video/tunlaw-penthouse.jpg', '/media/video/tunlaw-penthouse.mp4', '/media/video/tunlaw-penthouse.mp4', 'Washington', 'DC', null, null, null, false, true, false, 80),
  ('93000000-0000-4000-8000-000000000012', '8182-cobble-pond-way', '8182 Cobble Pond Way', 'Listing launch', 'Residential Real Estate', 2025, 'A quiet Manassas home, made impossible to scroll past.', 'A walkthrough listing film for a beautifully maintained Manassas home, edited vertical-first for the Just Listed post.', 'A walkthrough listing film for a beautifully maintained Manassas home, edited vertical-first for the Just Listed post.', array['creative', 'social']::text[], array['Listing Film', 'Social Media']::text[], '[]'::jsonb, null, null, 'A 4K gimbal walkthrough with on-screen captions, cut for Instagram and Reels.', null, '/media/video/cobble-pond.jpg', '/media/video/cobble-pond.mp4', '/media/video/cobble-pond.mp4', 'Manassas', 'VA', null, null, null, false, true, false, 90),
  ('93000000-0000-4000-8000-000000000013', '7906-garland-avenue', '7906 Garland Avenue', 'Listing launch', 'Residential Real Estate', 2025, 'Classic character, thoughtfully filmed.', 'A Just Listed film for a charming home that blends classic character with thoughtful updates, presented by the listing agent and cut for Instagram.', 'A Just Listed film for a charming home that blends classic character with thoughtful updates, presented by the listing agent and cut for Instagram.', array['creative', 'social']::text[], array['Listing Film', 'Social Media']::text[], '[]'::jsonb, null, null, 'An agent-presented 4K walkthrough, edited into a vertical film for the listing announcement.', null, '/media/video/garland.jpg', '/media/video/garland.mp4', '/media/video/garland.mp4', null, null, null, null, null, false, true, false, 100),
  ('93000000-0000-4000-8000-000000000014', '10009-murnane-street', '10009 Murnane Street', 'Listing launch', 'Residential Real Estate', 2025, 'Bright rooms, clean lines, a film that shows both.', 'A listing film that walks buyers through the home''s main living spaces in soft natural light.', 'A listing film that walks buyers through the home''s main living spaces in soft natural light.', array['creative']::text[], array['Listing Film']::text[], '[]'::jsonb, null, null, 'A 4K gimbal walkthrough graded for a clean, bright look.', null, '/media/video/murnane.jpg', '/media/video/murnane.mp4', '/media/video/murnane.mp4', null, null, null, null, null, false, true, false, 110),
  ('93000000-0000-4000-8000-000000000015', '9722-arnon-chapel-road', '9722 Arnon Chapel Road', 'Listing launch', 'Luxury Real Estate', 2025, 'Great Falls, from the front door to the pool.', 'A listing film for a Great Falls, Virginia home, with a widescreen cut for the listing page and a vertical version for social.', 'A listing film for a Great Falls, Virginia home, with a widescreen cut for the listing page and a vertical version for social.', array['creative', 'social']::text[], array['Listing Film', 'Vertical Reel']::text[], '[]'::jsonb, null, null, 'A 4K walkthrough shot on a gimbal and edited in two formats.', null, '/media/video/arnon-chapel.jpg', '/media/video/arnon-chapel.mp4', '/media/video/arnon-chapel.mp4', 'Great Falls', 'VA', null, null, null, false, true, false, 120),
  ('93000000-0000-4000-8000-000000000016', '224-stoic-street', '224 Stoic Street', 'Listing launch', 'Residential Real Estate', 2025, 'The backyard pool gets its close-up.', 'A Loudoun County listing film that opens on the backyard and pool, then moves through the home.', 'A Loudoun County listing film that opens on the backyard and pool, then moves through the home.', array['creative', 'social']::text[], array['Listing Film', 'Social Media']::text[], '[]'::jsonb, null, null, 'A 4K gimbal walkthrough cut for Instagram, with the exterior as the hook.', null, '/media/photos/chandelier-kitchen.jpg', '/media/video/stoic-pool.mp4', '/media/video/stoic-pool.mp4', 'Leesburg', 'VA', null, null, null, false, true, false, 130),
  ('93000000-0000-4000-8000-000000000017', 'right-fit-brewery-event', 'Brewery Night at 2 Silos', 'Right Fit Realty', 'Client Events', 2024, 'A client appreciation night, filmed like a festival.', 'Photo and video coverage of Right Fit Realty''s client event at 2 Silos Brewery — the Yard, the taproom and the people — edited into a one-minute recap and a full-length film.', 'Photo and video coverage of Right Fit Realty''s client event at 2 Silos Brewery — the Yard, the taproom and the people — edited into a one-minute recap and a full-length film.', array['creative', 'social']::text[], array['Event Film', 'Event Photography', 'Social Media']::text[], '[]'::jsonb, null, null, '4K cinema-camera coverage and stills through golden hour, cut into a one-minute social recap and a longer horizontal film.', null, '/media/photos/2-silos-stage.jpg', '/media/video/brewery-event.mp4', '/media/video/brewery-event.mp4', 'Manassas', 'VA', null, null, null, true, true, false, 25),
  ('90000000-0000-4000-8000-000000000001', 'solenne-hotels', 'Stay for the light', 'Solenne Hotels', 'Hospitality', 2025, 'Turning golden hour into a booking engine.', 'A boutique coastal hotel group was renting its best rooms to online travel agencies at a 20% commission. We rebuilt the brand around the one moment guests never stop photographing — and made booking direct the obvious move.', 'A boutique coastal hotel group was renting its best rooms to online travel agencies at a 20% commission. We rebuilt the brand around the one moment guests never stop photographing — and made booking direct the obvious move.', array['branding', 'paid-media', 'creative']::text[], array['Brand Strategy', 'Paid Media', 'Content Production', 'Web Design']::text[], '[{"value":"+217%","label":"Direct booking revenue"},{"value":"4.1x","label":"Return on ad spend"},{"value":"−38%","label":"OTA dependency"}]'::jsonb, 'Beautiful properties, forgettable brand. Guests loved the hotels but booked through third-party sites, and every campaign looked like every other resort ad in the feed.', 'Own golden hour. We positioned Solenne as the place the day ends best, built a member rate that rewards booking direct, and structured media around dream-trip planning windows instead of last-minute deals.', 'A three-day production captured sunrise-to-sunset content across four properties: hero films, 60+ vertical cuts and a photo library. A new direct-booking site loads in under a second and turns every page into a reason to book.', 'Direct revenue more than tripled within two seasons while commission costs fell, funding the next wave of creative.', 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=2400&q=80', null, null, null, null, 'They didn''t just run our marketing. They changed how we think about growth.', 'Camille Reyes', 'CMO, Solenne Hotels', true, true, true, 10),
  ('90000000-0000-4000-8000-000000000002', 'norrow-coffee', 'A morning ritual, rebuilt', 'Norrow Coffee Co.', 'Consumer Brands', 2025, 'From farmers-market favorite to national subscription brand.', 'A small-batch roaster with cult local demand and zero national awareness. We gave the brand a voice as bold as the coffee and a subscription engine to match.', 'A small-batch roaster with cult local demand and zero national awareness. We gave the brand a voice as bold as the coffee and a subscription engine to match.', array['branding', 'social', 'creative']::text[], array['Brand Strategy', 'Social Media', 'Content Production', 'Paid Media']::text[], '[{"value":"4.6x","label":"Return on ad spend"},{"value":"+182%","label":"Subscription revenue"},{"value":"2.3M","label":"Organic video views"}]'::jsonb, 'Great coffee, generic packaging and a website that treated subscriptions as an afterthought.', 'Sell the ritual, not the bean. A new identity, a first-subscription offer and a creator program that put Norrow in thousands of real kitchens.', 'Packaging, a product photography system, and a weekly short-form series filmed in-house — tested hook by hook against paid social audiences.', 'Subscriptions became the majority of revenue within a year, and organic content now fuels the best-performing ads.', 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=2400&q=80', null, null, null, null, 'The first campaign paid for the year. Everything after that was upside.', 'Owen Hart', 'Founder, Norrow Coffee Co.', true, true, true, 20),
  ('90000000-0000-4000-8000-000000000003', 'brightwater-realty', 'Listings that sell before the open house', 'Brightwater Realty', 'Real Estate', 2026, 'Every listing launched like a premiere.', 'A growing brokerage wanted listings — and agents — that stood out in a crowded market. We built a launch system: cinematic media, a property site and paid social for every home.', 'A growing brokerage wanted listings — and agents — that stood out in a crowded market. We built a launch system: cinematic media, a property site and paid social for every home.', array['creative', 'paid-media', 'web']::text[], array['Content Production', 'Paid Media', 'Web Design', 'AI Automation']::text[], '[{"value":"+312%","label":"Qualified buyer leads"},{"value":"9 days","label":"Median days on market"},{"value":"−38%","label":"Cost per lead"}]'::jsonb, 'Listing photos that blended in, lead forms that went unanswered for hours, and agents recruiting with nothing to show.', 'Make every listing an event: twilight photography, drone film and a vertical reel, launched with geo-targeted ads and instant AI lead follow-up.', 'A repeatable production and launch kit — photo, video, 3D tour and property website within 48 hours — plus automated lead routing that answers buyers in under a minute.', 'More qualified buyers per listing, faster sales and a recruiting story the brokerage now leads with.', '/media/work/fairmont-deck.jpg', null, null, null, null, 'Our listings look like film premieres now. Sellers ask for them by name.', 'Dana Whitfield', 'Managing Broker, Brightwater Realty', true, true, true, 30),
  ('90000000-0000-4000-8000-000000000004', 'pulse-athletics', 'Built to move', 'Pulse Athletics', 'Lifestyle', 2025, 'A boutique gym with a stadium-sized presence.', 'Three locations competing with national chains. We built a brand with attitude and a membership funnel that fills classes.', 'Three locations competing with national chains. We built a brand with attitude and a membership funnel that fills classes.', array['social', 'paid-media', 'web']::text[], array['Social Media', 'Paid Media', 'Web Design', 'Growth Strategy']::text[], '[{"value":"+188%","label":"New memberships"},{"value":"3.2x","label":"Return on ad spend"},{"value":"−61%","label":"Cost per acquisition"}]'::jsonb, 'Great coaches, empty 6 a.m. classes and ads that looked like every gym ad ever made.', 'Show the sweat. Member-led content, a free first-class offer and landing pages built for one thumb.', 'A monthly content day, trainer-led vertical series and a booking funnel that converts in three taps.', 'Classes waitlisted at all three locations and a fourth opening funded by the growth.', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=2400&q=80', null, null, null, null, 'Fast, sharp and honest about the numbers. That''s a rare combination.', 'Marcus Lee', 'CEO, Pulse Athletics', true, true, true, 40),
  ('90000000-0000-4000-8000-000000000005', 'ember-and-oak', 'A table worth the wait', 'Ember & Oak', 'Restaurants', 2024, 'Fully booked, five nights a week.', 'A chef-driven restaurant with a loyal core and quiet weeknights. We made the dining room the city''s favorite piece of content.', 'A chef-driven restaurant with a loyal core and quiet weeknights. We made the dining room the city''s favorite piece of content.', array['social', 'creative']::text[], array['Social Media', 'Content Production']::text[], '[{"value":"+96%","label":"Weeknight reservations"},{"value":"1.4M","label":"Reel views"},{"value":"+54%","label":"Private events revenue"}]'::jsonb, 'Incredible food photographed under fluorescent kitchen light, posted sporadically.', 'Behind the pass: the fire, the plating, the people. A consistent weekly cadence and a reservations-first call to action.', 'Monthly content shoots, chef-hosted reels and a private-events landing page with instant inquiry routing.', 'Weeknights doubled and private dining became the fastest-growing revenue line.', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=2400&q=80', null, null, null, null, null, null, null, false, true, true, 50),
  ('90000000-0000-4000-8000-000000000006', 'vector-labs', 'Complex product, simple story', 'Vector Labs', 'Technology', 2025, 'Making enterprise AI feel obvious.', 'A powerful platform explained with jargon. We found the one-sentence story and built a site and content engine around it.', 'A powerful platform explained with jargon. We found the one-sentence story and built a site and content engine around it.', array['branding', 'web']::text[], array['Brand Strategy', 'Web Design', 'SEO + Content']::text[], '[{"value":"+140%","label":"Organic traffic"},{"value":"2.7x","label":"Demo requests"},{"value":"−41%","label":"Bounce rate"}]'::jsonb, 'Buyers couldn''t tell what the product did in the first ten seconds.', 'Lead with outcomes, prove with product, and publish the answers buyers were already searching for.', 'Messaging architecture, a new identity system, a Next.js site and a 40-article editorial program.', 'Search became the top pipeline source and sales calls start further down the funnel.', 'https://images.unsplash.com/photo-1531297484001-80022131f5a1?auto=format&fit=crop&w=2400&q=80', null, null, null, null, null, null, null, false, true, true, 60),
  ('90000000-0000-4000-8000-000000000007', 'lumiere-skin', 'Glow, engineered', 'Lumière Skin', 'Consumer Brands', 2024, 'Clinical skincare that finally looks the part.', 'Dermatologist-developed formulas in packaging that said drugstore. A rebrand, a launch film and performance media that earned retail shelf space.', 'Dermatologist-developed formulas in packaging that said drugstore. A rebrand, a launch film and performance media that earned retail shelf space.', array['branding', 'creative', 'paid-media']::text[], array['Brand Strategy', 'Content Production', 'Paid Media']::text[], '[{"value":"5.1x","label":"Launch ROAS"},{"value":"+230%","label":"Retail doors"},{"value":"3.8M","label":"Launch impressions"}]'::jsonb, 'Premium results, commodity perception.', 'Science you can see: macro product film, clinical proof up front, and a launch built for both DTC and retail buyers.', 'Identity and packaging, a hero launch film, and a 12-week paid social launch with creator seeding.', 'Sold out the first run and secured national retail placement.', 'https://images.unsplash.com/photo-1570172619644-dfd03ed5d881?auto=format&fit=crop&w=2400&q=80', null, null, null, null, null, null, null, false, true, true, 70)
